	@Test
	void partiallyOpenedNativeFamilyReleasesCapacityOnInterruptionAndCanRetry(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory)
			throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setSketchEstimatorEnabled(false)
				.setBackgroundRawSamplingEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false)
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(32L * 1024L * 1024L);
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		store.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			assertTrue(store.getBackingStore().awaitFrontierStatisticsReady(TimeUnit.SECONDS.toMillis(30)));
			var before = store.rebuildFrontierStatistics();
			TripleStore triples = store.getBackingStore().getTripleStore();
			triples.commitNamespaceSnapshot(Map.of("native-family", "urn:native-family:"));
			assertTrue(triples.snapshotCoordinates()[0] != before.coveredEpoch());
			TxnManager manager = triples.getTxnManager();
			List<TxnManager.Txn> managedReaders = new ArrayList<>();
			List<Long> foreignReaders = new ArrayList<>();
			CompletableFuture<Void> rebuilt = new CompletableFuture<>();
			AtomicReference<Thread> workerRef = new AtomicReference<>();
			AtomicInteger opened = new AtomicInteger();
			Thread rebuild = Thread.ofPlatform().unstarted(() -> {
				try {
					store.rebuildFrontierStatistics();
					rebuilt.complete(null);
				} catch (Throwable failure) {
					rebuilt.completeExceptionally(failure);
				}
			});
			workerRef.set(rebuild);
			try {
				int available = manager.availableReadTxnSlots(TxnManager.POOL_SIZE, 0);
				assertTrue(available > 2);
				managedReaders.addAll(Arrays.asList(manager.createReadTxnPinnedFamily(available - 2, () -> 0L)));
				assertEquals(2, manager.availableReadTxnSlots(TxnManager.POOL_SIZE, 0));
				try (MemoryStack stack = MemoryStack.stackPush()) {
					PointerBuffer pointer = stack.mallocPointer(1);
					int rc;
					while ((rc = mdb_txn_begin(triples.env, 0L, MDB_RDONLY, pointer)) == MDB_SUCCESS) {
						foreignReaders.add(pointer.get(0));
					}
					assertEquals(MDB_READERS_FULL, rc);
					assertTrue(foreignReaders.size() > 1);
					mdb_txn_abort(foreignReaders.remove(foreignReaders.size() - 1));
				}
				manager.setAdmissionObserverForTest(txn -> {
					if (Thread.currentThread() == workerRef.get()) {
						opened.incrementAndGet();
					}
				});
				rebuild.start();
				long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
				boolean waiting = false;
				while (!rebuilt.isDone() && System.nanoTime() < deadline) {
					ThreadInfo info = ManagementFactory.getThreadMXBean().getThreadInfo(rebuild.threadId(), 50);
					if (opened.get() >= 2 && info != null
							&& Arrays.stream(info.getStackTrace())
									.anyMatch(frame -> frame.getClassName().contains("TxnManager")
											&& (frame.getMethodName().equals("withReadersFullRetry")
													|| frame.getMethodName().equals("awaitReaderRelease")))) {
						waiting = true;
						break;
					}
					Thread.onSpinWait();
				}
				assertTrue(waiting,
						"the probe and one family reader must start before native pressure blocks the family");
				int slotsWhileWaiting = manager.availableReadTxnSlots(TxnManager.POOL_SIZE, 0);
				long writeStamp = manager.lockManager().tryWriteLock();
				if (writeStamp != 0L) {
					manager.lockManager().unlockWrite(writeStamp);
				}
				rebuild.interrupt();
				try {
					rebuilt.get(10, TimeUnit.SECONDS);
				} catch (ExecutionException failure) {
					assertTrue(failure.getCause() instanceof org.eclipse.rdf4j.sail.SailException);
				}
				assertEquals(2, slotsWhileWaiting, "a partial family must not retain ordinary permits");
				assertTrue(writeStamp != 0L, "a native writer must not wait behind a table-capacity wait");
				assertEquals(2, manager.availableReadTxnSlots(TxnManager.POOL_SIZE, 0));
			} finally {
				manager.setAdmissionObserverForTest(null);
				rebuild.interrupt();
				for (long txn : foreignReaders) {
					mdb_txn_abort(txn);
				}
				for (TxnManager.Txn txn : managedReaders) {
					txn.close();
				}
				rebuild.join(TimeUnit.SECONDS.toMillis(20));
				assertFalse(rebuild.isAlive());
			}
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability(),
					"native reader capacity must be reusable after the interrupted family");
		} finally {
			store.shutDown();
		}
	}
